#!/usr/bin/env python3
"""Correlation tests on generated byte streams.

Educational only.  Low correlation is necessary but not sufficient for
cryptographic unpredictability.
"""

from __future__ import annotations

import argparse
import statistics
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[1] / "src"))

from pyentropy import RNG, TestRNG  # noqa: E402


def lag_correlation(data: bytes, lag: int) -> float:
    if len(data) <= lag:
        return float("nan")
    xs = [float(b) for b in data]
    mean = statistics.fmean(xs)
    num = sum((xs[i] - mean) * (xs[i + lag] - mean) for i in range(len(xs) - lag))
    den = sum((x - mean) ** 2 for x in xs)
    return num / den if den else float("nan")


def main() -> int:
    parser = argparse.ArgumentParser(description="PyEntropy correlation tests")
    parser.add_argument("--bytes", type=int, default=50_000)
    args = parser.parse_args()

    print("Correlation tests (educational)")
    print("Low correlation ≠ cryptographic security.\n")

    rng = RNG()
    data = rng.bytes(args.bytes)
    for lag in (1, 2, 3, 8, 16, 32):
        print(f"lag {lag:2d}: {lag_correlation(data, lag):+.6f}")

    # Compare two independent generators
    a = RNG().bytes(4096)
    b = RNG().bytes(4096)
    xor_weight = sum(bin(x ^ y).count("1") for x, y in zip(a, b, strict=True))
    print(f"\nCross-instance Hamming weight (4096 B): {xor_weight} (ideal ~16384)")

    # Deterministic control: TestRNG should be perfectly reproducible
    t1 = TestRNG(b"corr").bytes(256)
    t2 = TestRNG(b"corr").bytes(256)
    print(f"TestRNG reproducibility: {t1 == t2}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
